    [gambling_dec] smallint,
    [greenspace_active_dec] smallint,
    [hospital_dec] smallint,
    [leisure_dec] smallint,
    [pharmacy_dec] smallint,
    [pub_bar_dec] smallint,
    [tobacco_dec] smallint,
