SELECT
    NULLIF([ahah_version], N''),
    CONVERT(smallint, NULLIF([datazone_vintage], '')),
    NULLIF([datazone_code], N''),
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([GP], ''))) = [GP] THEN CONVERT(decimal(38,20), [GP]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([bluespace], ''))) = [bluespace] THEN CONVERT(decimal(38,20), [bluespace]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([dentist], ''))) = [dentist] THEN CONVERT(decimal(38,20), [dentist]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([fast_food], ''))) = [fast_food] THEN CONVERT(decimal(38,20), [fast_food]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([gambling], ''))) = [gambling] THEN CONVERT(decimal(38,20), [gambling]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([greenspace_active], ''))) = [greenspace_active] THEN CONVERT(decimal(38,20), [greenspace_active]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([hospital], ''))) = [hospital] THEN CONVERT(decimal(38,20), [hospital]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([leisure], ''))) = [leisure] THEN CONVERT(decimal(38,20), [leisure]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([pharmacy], ''))) = [pharmacy] THEN CONVERT(decimal(38,20), [pharmacy]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([pub_bar], ''))) = [pub_bar] THEN CONVERT(decimal(38,20), [pub_bar]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([tobacco], ''))) = [tobacco] THEN CONVERT(decimal(38,20), [tobacco]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([NO2], ''))) = [NO2] THEN CONVERT(decimal(38,20), [NO2]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([PM10], ''))) = [PM10] THEN CONVERT(decimal(38,20), [PM10]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([SO2], ''))) = [SO2] THEN CONVERT(decimal(38,20), [SO2]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([greenspace], ''))) = [greenspace] THEN CONVERT(decimal(38,20), [greenspace]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([off_licence], ''))) = [off_licence] THEN CONVERT(decimal(38,20), [off_licence]) END,
    CONVERT(tinyint, NULLIF([ur], '')),
    CONVERT(int, NULLIF([GP_rnk], '')),
    CONVERT(int, NULLIF([bluespace_rnk], '')),
    CONVERT(int, NULLIF([dentist_rnk], '')),
    CONVERT(int, NULLIF([fast_food_rnk], '')),
    CONVERT(int, NULLIF([gambling_rnk], '')),
    CONVERT(int, NULLIF([greenspace_active_rnk], '')),
    CONVERT(int, NULLIF([hospital_rnk], '')),
    CONVERT(int, NULLIF([leisure_rnk], '')),
    CONVERT(int, NULLIF([pharmacy_rnk], '')),
    CONVERT(int, NULLIF([pub_bar_rnk], '')),
    CONVERT(int, NULLIF([tobacco_rnk], '')),
    CONVERT(int, NULLIF([NO2_rnk], '')),
    CONVERT(int, NULLIF([PM10_rnk], '')),
    CONVERT(int, NULLIF([SO2_rnk], '')),
    CONVERT(int, NULLIF([greenspace_rnk], '')),
    CONVERT(tinyint, NULLIF([GP_pct], '')),
    CONVERT(tinyint, NULLIF([bluespace_pct], '')),
    CONVERT(tinyint, NULLIF([dentist_pct], '')),
    CONVERT(tinyint, NULLIF([fast_food_pct], '')),
    CONVERT(tinyint, NULLIF([gambling_pct], '')),
    CONVERT(tinyint, NULLIF([greenspace_active_pct], '')),
    CONVERT(tinyint, NULLIF([hospital_pct], '')),
    CONVERT(tinyint, NULLIF([leisure_pct], '')),
    CONVERT(tinyint, NULLIF([pharmacy_pct], '')),
    CONVERT(tinyint, NULLIF([pub_bar_pct], '')),
    CONVERT(tinyint, NULLIF([tobacco_pct], '')),
    CONVERT(tinyint, NULLIF([NO2_pct], '')),
    CONVERT(tinyint, NULLIF([PM10_pct], '')),
    CONVERT(tinyint, NULLIF([SO2_pct], '')),
    CONVERT(tinyint, NULLIF([greenspace_pct], '')),
    CONVERT(smallint, NULLIF([GP_dec], '')),
    CONVERT(smallint, NULLIF([bluespace_dec], '')),
    CONVERT(smallint, NULLIF([dentist_dec], '')),
    CONVERT(smallint, NULLIF([fast_food_dec], '')),
    CONVERT(smallint, NULLIF([gambling_dec], '')),
    CONVERT(smallint, NULLIF([greenspace_active_dec], '')),
    CONVERT(smallint, NULLIF([hospital_dec], '')),
    CONVERT(smallint, NULLIF([leisure_dec], '')),
    CONVERT(smallint, NULLIF([pharmacy_dec], '')),
    CONVERT(smallint, NULLIF([pub_bar_dec], '')),
    CONVERT(smallint, NULLIF([tobacco_dec], '')),
    CONVERT(smallint, NULLIF([NO2_dec], '')),
    CONVERT(smallint, NULLIF([PM10_dec], '')),
    CONVERT(smallint, NULLIF([SO2_dec], '')),
    CONVERT(smallint, NULLIF([greenspace_dec], '')),
    CONVERT(smallint, NULLIF([off_licence_dec], '')),
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([domain_h], ''))) = [domain_h] THEN CONVERT(decimal(38,20), [domain_h]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([domain_g], ''))) = [domain_g] THEN CONVERT(decimal(38,20), [domain_g]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([domain_e], ''))) = [domain_e] THEN CONVERT(decimal(38,20), [domain_e]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([domain_r], ''))) = [domain_r] THEN CONVERT(decimal(38,20), [domain_r]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([domain_h_exp], ''))) = [domain_h_exp] THEN CONVERT(decimal(38,20), [domain_h_exp]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([domain_g_exp], ''))) = [domain_g_exp] THEN CONVERT(decimal(38,20), [domain_g_exp]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([domain_e_exp], ''))) = [domain_e_exp] THEN CONVERT(decimal(38,20), [domain_e_exp]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(38,20), NULLIF([domain_r_exp], ''))) = [domain_r_exp] THEN CONVERT(decimal(38,20), [domain_r_exp]) END,
    CONVERT(int, NULLIF([domain_h_rnk], '')),
